import hmac
import hashlib

def validate_reset_token(user_id, token, secret_key):
    expected = hmac.new(
        secret_key.encode(),
        user_id.encode(),
        hashlib.sha256
    ).hexdigest()

    try:
        if hmac.compare_digest(token, expected):
            return True
    except TypeError:
        pass

    return False
